"""Self-contained offline viewer; no dependencies, network calls or raw private logs."""
import json
from pathlib import Path

def render_dashboard(result,path):
 data=json.dumps({'methods':result['methods'],'tasks':result['tasks'],'purchases':result.get('purchases',[]),'method_counts':result['method_counts'],'task_counts':result['task_counts'],'tests':result['regressions'],'generated':result['generated_utc']}).replace('<','\\u003c')
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Village Life restoration checks</title>
<style>body{font:16px/1.5 system-ui;background:#f3f5f4;color:#182b28;margin:0}main{max-width:1250px;margin:auto;padding:32px}h1{margin:0}header{background:#183b32;color:white;padding:28px;border-radius:12px}header p{max-width:850px}section{margin-top:24px;padding:24px;background:white;border-radius:12px}.counts{display:flex;flex-wrap:wrap;gap:12px}.count{padding:14px;background:#eaf2ee;border-radius:8px}input,select,button{font:inherit;padding:8px;margin:5px 8px 5px 0}button{cursor:pointer}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:9px;border-bottom:1px solid #dde5e0;vertical-align:top}th{position:sticky;top:0;background:#eaf2ee}code{overflow-wrap:anywhere}#results{overflow:auto;max-height:650px}small{color:#49625b}.warn{background:#fff4dc;padding:16px;border-radius:8px}</style>
<main><header><h1>Village Life restoration checks</h1><p>A repeatable checklist built from the original client, packaged rules and disposable server tests.</p><p id="stamp"></p></header>
<section><h2>What this run proves</h2><div class="counts" id="counts"></div><p class="warn">A passing recipe checks server costs, base timers, saving/reloading and repeat collection. It does not prove the original game can reach or display that feature. Disabled events and empty responses are listed as unfinished policies.</p><p>The audit does not launch the game or change your live village. The old server code is not contained in the client. Compiled names can include unused or debug features.</p></section>
<section><h2>Explore the checklist</h2><button id="methods">Server operations</button><button id="tasks">Original task definitions</button><button id="purchases">Material purchases</button><br><input id="search" type="search" placeholder="Search a name, method or blocker" aria-label="Search"><select id="status" aria-label="Status filter"></select><p id="total"></p><div id="results"></div></section>
<section><h2>Next work</h2><ol><li>Investigate observed missing calls first.</li><li>Recover request fields and response structures for each shared missing system.</li><li>Add a disposable scenario, implement it, and rerun the checks.</li><li>Verify the original game's buttons, animations and restart behaviour.</li><li>Release a versioned package with save migration and rollback checks.</li></ol><p>Detailed evidence and backlog: <a href="REPORT.md">REPORT.md</a>. Sortable lists: <a href="methods.csv">operations</a>, <a href="tasks.csv">tasks</a>, <a href="purchases.csv">purchases</a>, <a href="original-script-symbols.csv">original script symbols</a>. Test output: <a href="regression-tests.txt">regression log</a>.</p></section></main>
<script id="audit-data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('audit-data').textContent);let mode='methods';
const labels={passed_server_fixture:'Passed server scenario',not_implemented:'Not implemented',fixture_missing:'Needs an original source mapping',rejected_fixture:'Rejected; needs investigation',failed:'Test failure',not_direct_gem_purchase:'No direct gem purchase in table',exercised_in_passing_regression:'Exercised in passing test',declared_not_exercised:'Handler needs a successful scenario',disabled_or_empty_policy:'Disabled or empty policy'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.getElementById('stamp').textContent='Run '+data.generated;
for(const [name,value] of Object.entries(data.task_counts)){const d=document.createElement('div');d.className='count';d.textContent=value+'  -  '+(labels[name]||name);document.getElementById('counts').appendChild(d)}
function rows(){return mode==='methods'?Object.entries(data.methods).map(([name,r])=>({name,...r})):mode==='tasks'?data.tasks:data.purchases}
function setMode(next){mode=next;const select=document.getElementById('status');select.replaceChildren();for(const value of ['',...new Set(rows().map(r=>r.status))]){const o=document.createElement('option');o.value=value;o.textContent=value?(labels[value]||value):'All statuses';select.appendChild(o)}draw()}
function draw(){const q=document.getElementById('search').value.toLowerCase(),status=document.getElementById('status').value;const filtered=rows().filter(r=>(!status||r.status===status)&&JSON.stringify(r).toLowerCase().includes(q));document.getElementById('total').textContent=filtered.length+' of '+rows().length+' entries';let body='';for(const r of filtered){if(mode==='methods'){body+='<tr><td><code>'+esc(r.name)+'</code></td><td>'+esc(labels[r.status]||r.status)+'</td><td>'+r.regression_tests.length+'</td><td>'+esc(r.observed_codes.join(', '))+'</td></tr>'}else{body+='<tr><td>'+esc(mode==='tasks'?r.task_id:r.material_id)+'</td><td>'+esc(r.name)+'</td><td>'+esc(labels[r.status]||r.status)+'</td><td>'+esc(r.reason||r.checks.join(', '))+'</td></tr>'}}const titles=mode==='methods'?['Operation','Coverage','Passing test references','Historical response codes']:[mode==='tasks'?'Task ID':'Material ID','Original name','Coverage','Checks or blocker'];document.getElementById('results').innerHTML='<table><thead><tr>'+titles.map(t=>'<th>'+t+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table>'}
document.getElementById('methods').onclick=()=>setMode('methods');document.getElementById('tasks').onclick=()=>setMode('tasks');document.getElementById('purchases').onclick=()=>setMode('purchases');document.getElementById('search').oninput=draw;document.getElementById('status').onchange=draw;setMode('methods');
</script></html>'''
 Path(path).write_text(page.replace('__DATA__',data),encoding='utf-8')
